import sys

def solve():
    line = sys.stdin.read().strip()
    if not line:
        return
    x = line
    if x.startswith('-'):
        print("false")
    elif x == x[::-1]:
        print("true")
    else:
        print("false")

if __name__ == '__main__':
    solve()

