#include <stdio.h>
#include <string.h>

int main() {
    char s[64];
    if (scanf("%63s", s) != 1) return 0;
    if (s[0] == '-') {
        printf("false\n");
        return 0;
    }
    int len = strlen(s);
    for (int i = 0; i < len / 2; i++) {
        if (s[i] != s[len - 1 - i]) {
            printf("false\n");
            return 0;
        }
    }
    printf("true\n");
    return 0;
}
